# =============================================================================
# R/assay_lineage.R
#
# WS3, deliverable 2. Validation for metadata/assay_lineage.csv.
#
# The table itself is generated by scripts/build_assay_lineage.R. This file
# holds only the validator, because it is called from a pipeline target
# (assay_lineage_check in _targets.R) and tar_source() loads R/ but not
# scripts/.
#
# The rule the gate enforces: a country-outcome cannot be modelled without a
# recorded provenance row. UNKNOWN is an acceptable VALUE in a lineage row, and
# most of the specimen, instrument and laboratory cells are UNKNOWN today. A
# missing ROW is not acceptable, because it means an outcome is being modelled
# that nobody has written down the measurement basis for. A blank source cell is
# also not acceptable, because it means a value was asserted with nothing behind
# it.
# =============================================================================

ASSAY_LINEAGE_PATH <- function() here::here("metadata", "assay_lineage.csv")

ASSAY_LINEAGE_REQUIRED_COLS <- c(
  "survey", "country", "outcome_tag", "population", "biomarker",
  "specimen", "instrument_or_kit", "laboratory",
  "adjustment_applied", "cutoff",
  "source_specimen", "source_instrument", "source_laboratory",
  "source_adjustment", "source_cutoff"
)

#' Validate the assay-lineage table against the configured outcomes.
#'
#' Never stops on its own, so a caller can decide whether a gap is fatal. The
#' pipeline target treats it as fatal; the command-line script exits 1.
#'
#' @param path path to assay_lineage.csv
#' @param configs get_country_configs() output
#' @return list(ok, missing, extra, blank_sources, n_required, n_rows)
validate_assay_lineage <- function(path = ASSAY_LINEAGE_PATH(),
                                   configs = get_country_configs()) {
  if (!file.exists(path))
    return(list(ok = FALSE, missing = "<file absent>", extra = character(0),
                blank_sources = integer(0), n_required = NA_integer_, n_rows = 0L))

  lin <- readr::read_csv(path, show_col_types = FALSE, progress = FALSE)

  missing_cols <- setdiff(ASSAY_LINEAGE_REQUIRED_COLS, names(lin))
  if (length(missing_cols))
    return(list(ok = FALSE,
                missing = paste("columns:", paste(missing_cols, collapse = ", ")),
                extra = character(0), blank_sources = integer(0),
                n_required = NA_integer_, n_rows = nrow(lin)))

  required <- unlist(lapply(names(configs), function(cn)
    paste(configs[[cn]]$country, names(configs[[cn]]$outcomes), sep = "|")))
  present <- paste(lin$country, lin$outcome_tag, sep = "|")

  src_cols <- grep("^source_", names(lin), value = TRUE)
  blank_src <- vapply(src_cols, function(cn)
    sum(is.na(lin[[cn]]) | trimws(as.character(lin[[cn]])) == ""), integer(1))

  list(ok = length(setdiff(required, present)) == 0 && sum(blank_src) == 0,
       missing = setdiff(required, present),
       extra = setdiff(present, required),
       blank_sources = blank_src[blank_src > 0],
       n_required = length(required),
       n_rows = nrow(lin))
}
